         {
             Argument.AssertNotNullOrEmpty(apiVersion, nameof(apiVersion));

             ResourceApiVersionOverrides[resourceType] = apiVersion;
         }

         /// <summary>
         /// Sets the api versions from an Azure Stack profile.
         /// </summary>
